referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const ids = d.elements.filter((e) => !e.disabled && !e.hidden).map((e) => e.id);
  let i = ids.indexOf(d.start);
  return d.moves.map((m) => {
    i = (i + (m === "forward" ? 1 : ids.length - 1)) % ids.length;
    return ids[i];
  });
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const ids = d.elements.filter((e: any) => !e.disabled && !e.hidden).map((e: any) => e.id);
  let i = ids.indexOf(d.start);
  return d.moves.map((m: string) => {
    i = (i + (m === "forward" ? 1 : ids.length - 1)) % ids.length;
    return ids[i];
  });
}
